window.DOSIK=window.DOSIK||{};DOSIK["sm_civil"]={"1":[{"t":"table","title":"민법의 법원","head":["주제","내용"],"rows":[["적용 순서","제1조는 민사에 관하여 법률, 관습법, 조리의 순서로 적용한다고 정한다 · 법률은 국회 제정 법률에 그치지 않고 긴급명령·긴급재정경제명령, 헌법에 따라 체결·공포된 조약과 일반적으로 승인된 국제법규, 대법원규칙, 조례도 민사에 관한 것이면 포함된다 · 판례는 대법원 전원합의체 판결의 법명제라도 법원(法源)이 아니다"],["관습법","법적 확신을 얻은 법규범이므로 당사자의 주장·증명이 없어도 법원(法院)이 직권으로 확정한다"],["사실인 관습","법률행위 해석의 표준이 될 뿐 법원(法源)이 아니고, 그 존재는 당사자가 주장·증명한다 · 대법원은 둘을 구별한다"],["관습법의 효력과 소멸","성문법을 보충하는 효력만 있어 제정법의 임의규정과 충돌하면 임의규정이 우선한다 · 관습법으로 승인된 뒤라도 구성원의 법적 확신이 사라지거나 사회 변화로 적용 시점의 전체 법질서에 반하게 되면 법적 규범으로서 효력을 잃는다"]]},{"t":"table","title":"신의칙","head":["주제","내용"],"rows":[["적용 범위","신의칙 위반과 권리남용은 법원의 직권조사사항이다 · 소멸시효 완성 항변도 신의칙의 지배를 받는다 · 유효하게 성립한 계약의 급부를 법원이 신의칙을 들어 감축하는 것은 원칙적으로 허용되지 않지만, 부당하게 과다한 변호사 보수 약정은 적당한 범위로 제한된다"],["신의칙 위반이 아닌 주장","법정대리인 동의 없이 신용구매계약을 맺은 미성년자의 취소, 강행법규를 위반한 자의 무효 주장, 토지거래허가가 없음을 이유로 한 무효 주장은 원칙적으로 신의칙에 반하지 않는다 · 이를 막으면 강행법규나 제한능력자 보호의 취지가 무너지기 때문이다"],["신의칙 위반이 되는 경우","무권대리인이 본인을 단독상속한 뒤 본인 지위에서 자기 무권대리행위의 추인을 거절하는 것 · 시효완성을 모르고 권리를 주장하지 않기로 해 놓고 나중에 시효를 주장하는 것 · 제3자 부동산을 채무자 명의로 명의신탁시킨 뒤 강제집행하는 것"],["보호의무","숙박업자는 고객의 안전을, 병원은 입원환자 소지품의 도난 방지를 배려할 신의칙상 보호의무를 진다 · 통상의 임대차에서 임대인은 임차인의 안전을 배려할 보호의무를 지지 않는다"]]},{"t":"tree","title":"권리남용과 실효","root":"권리남용·실효의 원칙","branches":[["권리남용","행사자에게 정당한 이익이 없고 오직 상대방에게 고통·손해를 주려는 목적이 있어야 인정되며, 얻는 이익보다 상대방 손해가 현저히 크다는 사정만으로는 부족하다"],["송전선","송전선이 지나는 것을 알고 토지를 산 자의 철거청구도 그것만으로 신의칙에 반하지 않는다"],["실효의 원칙","해제권에도 적용되며, 의무자에게 권리불행사를 신뢰할 정당한 사유가 있어야 한다"]]},{"t":"table","title":"권리의 분류와 변동","head":["구분","내용"],"rows":[["형성권","해제권·취소권·상계권·일방예약완결권·지상물매수청구권·부속물매수청구권"],["청구권과 항변권","임차인의 필요비상환청구권은 청구권, 동시이행항변권은 항변권이다"],["합의해지","형성권 행사가 아니라 새 계약이다"],["취득과 승계","취득시효·신축·무주물선점은 원시취득, 상속·회사합병은 포괄승계이며, 소유권은 양도·상속되므로 일신전속권이 아니다"]]}],"2":[{"t":"table","title":"권리능력과 의사능력","head":["주제","내용"],"rows":[["권리능력","사람은 생존한 동안 권리와 의무의 주체가 되고(제3조), 권리능력 규정은 강행규정이다"],["태아","불법행위 손해배상(부의 사망에 대한 자기 위자료 포함), 상속, 유증에서 이미 출생한 것으로 보지만 판례는 살아서 출생한 때 소급해 권리를 취득한다고 본다(정지조건설) · 그래서 사산되면 손해배상청구권이 생기지 않고, 태아 상태에서 법정대리인을 통한 증여의 수증도 할 수 없다"],["의사능력","연령으로 획일적으로 정하지 않고 구체적 법률행위마다 개별적으로 판단하며 행위능력만 객관적·획일적으로 판단한다 · 의사무능력자의 법률행위는 무효이고, 무효를 주장하는 쪽이 의사무능력을 증명한다 · 의사무능력자가 스스로 무효를 주장해도 신의칙에 반하지 않고, 반환범위는 현존이익에 한정된다"]]},{"t":"table","title":"미성년자","head":["주제","내용"],"rows":[["동의와 예외","성년은 19세이고(제4조), 미성년자의 법률행위에는 법정대리인의 동의가 필요하며 이 규정은 강행규정이고 동의는 묵시적으로도 할 수 있다 · 동의가 있었다는 증명책임은 유효를 주장하는 상대방에게 있다 · 무이자 차용도 반환채무를 지므로 동의가 필요하다 · 혼인한 미성년자는 성년으로 보고(제826조의2) 소송능력도 갖는다"],["단독행위","권리만 얻거나 의무만 면하는 행위, 처분을 허락받은 재산의 처분, 자기 노무에 따른 임금 청구, 타인의 대리행위, 만 17세 이상의 유언은 단독으로 할 수 있다"],["영업허락","영업의 종류를 특정해야 하고, 그 영업에 관해서는 성년자와 같은 행위능력이 생겨 법정대리인의 대리권이 소멸한다 · 영업허락을 취소·제한해도 선의의 제3자에게 대항하지 못한다(제8조 제2항)"]]},{"t":"table","title":"후견","head":["유형","내용"],"rows":[["성년후견","정신적 제약으로 사무처리능력이 지속적으로 결여된 사람이 대상이고, 개시심판에서 본인의 의사를 고려해야 한다(제9조 제2항) · 피성년후견인의 법률행위는 후견인 동의가 있어도 취소할 수 있으나, 가정법원이 취소할 수 없는 범위를 정할 수 있고 청구에 따라 변경할 수 있다 · 대가가 과도하지 않은 일용품 구입은 취소할 수 없고, 혼인했다고 능력이 넓어지지 않는다 · 법인도 성년후견인이 될 수 있다"],["한정후견","능력이 부족한 사람이 대상이고, 가정법원이 정한 동의 필요 행위를 동의 없이 하면 무효가 아니라 취소할 수 있다(제13조 제4항) · 성년후견을 청구해도 법원은 감정 결과에 따라 한정후견을 개시할 수 있다"],["특정후견","본인의 의사에 반하여 할 수 없고 기간 또는 사무 범위를 정해야 하며 행위능력을 제한하지 않는다 · 정한 기간이 지나면 종료심판 없이 끝난다"],["후견 유형 변경","피한정후견인이나 피특정후견인에게 성년후견을 개시할 때, 피성년후견인이나 피특정후견인에게 한정후견을 개시할 때에는 종전 후견의 종료심판을 함께 한다(제14조의3) · 한정후견종료심판은 장래를 향해 효력이 있다"]]},{"t":"table","title":"제한능력자의 상대방 보호","head":["주제","내용"],"rows":[["확답촉구","상대방은 1개월 이상의 기간을 정해 확답을 촉구할 수 있고, 선의·악의를 묻지 않는다 · 제한능력자가 아직 능력자가 아니면 법정대리인에게 촉구해야 하며 기간 내 확답을 발송하지 않으면 추인으로 본다(제15조)"],["철회·거절","계약의 철회는 계약 당시 제한능력자임을 몰랐던 상대방만 할 수 있고, 단독행위의 거절은 상대방이 할 수 있으며 철회·거절은 제한능력자에게도 할 수 있다(제16조)"],["속임수","제한능력자가 속임수로 능력자로 믿게 하면 취소할 수 없고, 동의가 있는 것처럼 속인 경우는 미성년자와 피한정후견인에게만 같은 효과가 있다(제17조) · 피성년후견인은 동의가 있어도 취소할 수 있으므로 동의를 꾸며도 취소권이 남는다"],["취소의 효과","제한능력자는 단독으로 취소할 수 있고, 제한능력 취소는 선의의 제3자에게도 대항하며 받은 이익은 현존하는 한도에서 상환하고 금전 이득은 현존하는 것으로 추정된다"]]}],"3":[{"t":"table","title":"주소","head":["주제","내용"],"rows":[["주소","생활의 근거되는 곳이 주소이고 주소는 동시에 두 곳 이상 있을 수 있다(제18조)"],["거소와 가주소","주소를 알 수 없거나 국내에 주소가 없으면 거소를 주소로 보고, 어느 행위에 가주소를 정하면 그 행위에 관하여는 가주소를 주소로 본다(제21조)"],["법인","법인은 그 성질상 부재자가 될 수 없다"]]},{"t":"table","title":"부재자 재산관리","head":["주제","내용"],"rows":[["법원의 처분","부재자가 재산관리인을 정하지 않았거나 부재 중 관리인의 권한이 소멸한 때 법원은 이해관계인이나 검사의 청구로 재산관리에 필요한 처분을 명하여야 한다(제22조 제1항) · 이때 법원이 하는 것은 실종선고가 아니다 · 법원의 관리는 부재자가 관리인을 정하거나 스스로 관리할 수 있게 된 때, 사망하거나 실종선고를 받은 때 끝나고 행방불명은 개시 요건일 뿐 종료사유가 아니다"],["법원 선임 관리인","법정대리인으로서 선량한 관리자의 주의로 직무를 처리하고 관리할 재산목록을 작성하여야 한다(제24조 제1항) · 법원은 그에게 상당한 담보를 제공하게 할 수 있고 부재자의 재산으로 상당한 보수를 지급할 수 있다(제26조) · 부재자의 사망을 확인했더라도 선임결정이 취소되기 전까지는 권한을 행사하며 그동안 한 권한 내 행위는 실종기간 만료 뒤에 한 것이라도 유효하다"],["처분 허가","제118조의 보존·이용·개량 범위를 넘는 행위를 하려면 법원의 허가를 얻어야 한다(제25조) · 허가는 과거의 처분행위를 추인하는 방법으로도 할 수 있어 허가 없이 매각한 뒤 허가를 얻어 이전등기를 마치면 유효하다 · 매각 허가를 받았어도 부재자와 무관한 제3자의 채무만을 담보하려고 부재자 재산에 근저당권을 설정하는 것은 허가 범위를 벗어난다"],["부재자가 정한 관리인","위임계약에 따른 임의대리인이어서 처분권까지 위임받았다면 법원 허가 없이 처분할 수 있다 · 부재자의 생사가 분명하지 않게 되면 법원은 관리인을 개임할 수 있고(제23조), 권한을 넘는 행위에 허가가 필요하며 담보제공·보수 규정도 준용된다(제26조 제3항) · 처분권을 위임받았던 관리인이라도 실종을 이유로 개임된 뒤에는 허가를 받아야 처분할 수 있다"]]},{"t":"table","title":"실종선고","head":["주제","내용"],"rows":[["요건","보통실종은 생사불명이 5년간, 전쟁·선박 침몰·항공기 추락 같은 위난을 당한 특별실종은 위난이 종료한 후 1년간 계속되어야 한다(제27조) · 청구권자는 이해관계인이나 검사이며 이해관계인은 법률상 이해관계가 있는 자에 한정된다 · 선순위 상속인이 있으면 후순위 상속인은 청구할 수 없고 재산관리인은 이해관계인에 포함된다"],["할 수 없는 경우","가족관계등록부에 이미 사망으로 기재된 자에게는 그 추정력을 뒤집을 자료가 없는 한 실종선고를 할 수 없다 · 실종선고가 확정된 뒤 취소되지 않은 채 다시 내려진 실종선고는 효력이 없어 상속관계는 먼저 확정된 선고를 기준으로 판단한다"],["효과","실종선고를 받은 자는 실종기간이 만료한 때에 사망한 것으로 본다(제28조) · 실종된 날이나 선고가 확정된 날이 기준이 아니다 · 사망의 추정이 아니라 간주이므로 생환했더라도 선고를 취소하지 않는 한 반증으로 효과를 다툴 수 없고 효과는 종래 주소·거소를 중심으로 한 사법상 법률관계에만 미친다"],["취소","생존한 사실이나 실종기간 만료 때와 다른 시기에 사망한 사실이 증명되면 법원은 본인, 이해관계인 또는 검사의 청구로 실종선고를 취소한다(제29조 제1항) · 선고 후 취소 전에 선의로 한 행위는 효력을 잃지 않으며 계약은 당사자 쌍방이 선의여야 한다는 것이 통설이다 · 선고를 직접원인으로 재산을 취득한 자는 선의면 현존이익을, 악의면 받은 이익에 이자를 붙여 반환하고 손해까지 배상한다(제29조 제2항)"]]}],"4":[{"t":"table","title":"법인의 설립","head":["주제","내용"],"rows":[["설립","민법상 비영리법인은 주무관청의 허가를 얻어 설립하는 허가주의를 따르고(제32조) 허가 후 3주 내에 주된 사무소 소재지에서 설립등기를 함으로써 성립하며 재산 출연은 재단법인에만 필요하다"],["정관","설립행위는 정관을 서면으로 작성해 기명날인하는 요식행위이고 정관은 자치법규이며 필요적 기재사항은 목적, 명칭, 사무소 소재지, 자산, 이사 임면(사단법인은 사원자격 득실 추가)이다(제40조, 제43조) · 존립시기·해산사유와 대표권 제한은 필요적 기재사항이 아니고 재단법인 설립자가 명칭, 사무소, 이사 임면 방법을 정하지 않고 사망하면 법원이 정하지만 목적과 자산은 보충할 수 없다(제44조)"],["재단법인 출연재산","생전처분 설립에는 증여 규정을, 유언 설립에는 유증 규정을 준용하고(제47조) 출연재산은 각각 법인이 성립한 때, 유언의 효력이 발생한 때 법인에 귀속한다(제48조) · 판례는 출연자와 법인 사이에서는 등기 없이 귀속하지만 제3자에 대한 관계에서는 등기가 있어야 한다고 보아 출연자나 상속인에게서 사서 등기를 마친 제3자에게 법인은 대항하지 못한다 · 출연자는 법인 성립 뒤에도 착오를 이유로 출연을 취소할 수 있고 하자를 알고 알리지 않은 경우에만 담보책임을 진다"],["정관 변경","사단법인 정관 변경은 총사원 3분의 2 이상의 동의가 필요한 사원총회의 전속 권한이고 주무관청의 허가를 얻어야 효력이 생긴다(제42조) · 재단법인은 정관에 변경방법이 있거나 목적 달성이 불능일 때 설립취지를 참작해 주무관청 허가를 얻어 바꿀 수 있다(제45조, 제46조) · 임의적 기재사항도 정관에 적은 이상 변경 절차를 거치고 기본재산의 편입·처분은 정관 변경이어서 허가가 필요하지만 기본재산에 저당권을 설정하는 것은 허가 대상이 아니라는 것이 판례다"]]},{"t":"table","title":"법인의 기관","head":["주제","내용"],"rows":[["이사의 대표권","이사는 필수기관이고 감사는 임의기관이며 이사가 여럿이면 대표는 각자 하고(제59조) 사무집행은 정관에 다른 규정이 없으면 이사 과반수로 정한다(제58조) · 대표권 제한은 정관에 기재해야 효력이 있고 등기하지 않으면 악의의 제3자에게도 대항하지 못한다(제60조) · 정관에 해임사유를 정했으면 그 밖의 사유로는 원칙적으로 해임할 수 없지만 중대한 의무위반 같은 특별한 사정이 있으면 해임할 수 있고 사임은 주무관청 허가 없이 법인에 대한 의사표시로 한다"],["대리인·임시이사·특별대리인","이사는 금지되지 않은 사항에 한해 특정한 행위를 대리하게 할 수 있을 뿐이어서 대표권을 포괄적으로 위임받은 자의 행위는 법인에 효력이 없다(제62조) · 이사 결원으로 손해가 생길 염려가 있으면 법원이 임시이사를 선임하고(제63조) 임시이사는 정식이사와 같은 권한을 가지며 이 규정은 비법인사단에 유추된다 · 법인과 이사의 이익이 상반하는 사항에서는 그 이사에게 대표권이 없고 법원이 특별대리인을 선임한다(제64조)"],["사원총회","이사는 매년 1회 이상 통상총회를 소집하고(제69조) 총사원 5분의 1 이상이 목적사항을 제시해 청구하면 임시총회를 소집하며 청구 후 2주 내에 절차를 밟지 않으면 청구한 사원이 법원 허가를 얻어 소집한다 · 소집은 1주간 전에 목적사항을 적은 통지를 발송하면 되고 통지하지 않은 사항의 결의는 원칙적으로 무효다 · 결의는 사원 과반수 출석과 출석 사원 결의권 과반수로 하고 서면·대리인 행사도 출석으로 보며 법인과 관계사항이 걸린 사원은 결의권이 없다(제74조)"]]},{"t":"table","title":"책임·해산·비법인사단","head":["주제","내용"],"rows":[["불법행위책임","대표기관이 직무에 관하여 타인에게 손해를 가하면 법인은 사용자책임이 아니라 제35조의 책임을 지고 대표자 개인도 면책되지 않으며 등기 없이 실질적으로 운영하는 자도 대표자에 포함된다 · 대표권 없는 이사나 감사의 행위로는 성립하지 않고 외형상 직무행위면 법령 위반이라도 직무관련성이 인정되지만 피해자가 직무 아님을 알았거나 중대한 과실로 몰랐다면 책임이 없다 · 과실상계는 적용되며 목적범위 외 행위는 법인 책임이 아니고 그 의결에 찬성하거나 집행한 사원·이사가 연대하여 배상한다"],["해산과 청산","공통 해산사유는 존립기간 만료, 목적 달성·불능, 파산, 설립허가 취소이고 사단법인은 사원이 없게 된 때와 총사원 4분의 3 이상의 해산 결의가 더해진다(제77조, 제78조) · 파산 외의 해산이면 이사가 청산인이 되고 해산·청산은 법원이 검사·감독하며 청산인은 2월 내 3회 이상 공고로 채권신고를 최고하되 알고 있는 채권자는 신고가 없어도 제외하지 못하고 신고기간 중 변제를 못해도 지연손해는 배상한다 · 청산법인은 청산 목적 범위에서만 존속하므로 청산종결등기를 했어도 사무가 남으면 소멸하지 않는다"],["법인 아닌 사단","단체성의 강약으로 조합과 구별하며 대표자가 있으면 소송 당사자와 등기권리자가 될 수 있고 재산은 총유하며 법인격을 전제로 한 규정을 빼고 사단법인 규정과 제35조가 유추된다 · 교회·사찰의 분열은 인정되지 않고 총유물의 관리·처분은 규약이 없으면 총회 결의를 거쳐야 하며 구성원 개인은 총회 결의를 거쳐도 총유재산 소송의 당사자가 될 수 없다 · 채무의 승인은 총유물의 관리·처분행위가 아니고 정관상 대표권 제한을 어긴 거래는 상대방이 알았거나 알 수 있었을 때만 무효다"]]}],"5":[{"t":"table","title":"물건과 부동산","head":["주제","내용"],"rows":[["물건의 정의","물건은 유체물 및 전기 기타 관리할 수 있는 자연력이고(제98조) 관리할 수 있다는 것은 배타적 지배가 가능해 거래 객체가 될 수 있다는 뜻이다 · 권리는 물건이 아니므로 무기명채권도 동산이 아니며 금전, 전기, 신체에서 분리된 머리카락은 동산이다 · 유체·유골은 매장·관리·제사의 대상인 유체물로서 제사주재자에게 승계되지만 제사주재자도 이를 포기하거나 임의로 처분할 수 없다"],["부동산과 동산","토지 및 그 정착물은 부동산이고 부동산 이외의 물건은 동산이며(제99조) 둘 다 요건은 다르지만 취득시효의 대상이 된다 · 토지의 개수는 지적공부상의 필수로 정해지므로 1필 토지의 일부를 별개 부동산으로 하려면 분필절차를 거쳐야 하고 그 절차 없이 등기부상 분필등기만 해서는 분필 효과가 없다 · 지상권·지역권·전세권 같은 용익물권은 분할하지 않은 1필 토지의 일부에도 설정할 수 있다"],["토지의 구성부분","지하수, 온천수, 토석은 토지의 구성부분이어서 따로 거래의 객체가 되지 못하고 온천에 관한 권리는 관습법상 물권으로 인정되지 않는다 · 공사가 중단되어 사회통념상 독립한 건물로 볼 수 없는 정착물은 토지의 부합물에 불과하다"],["토지와 별개인 정착물","건물은 최소한의 기둥, 지붕, 주벽을 갖추면 토지와 별개의 부동산이 되고 지붕과 벽면을 갖추어 토지에 견고하게 부착한 저유조도 건물로 본다 · 입목등기를 마친 수목의 집단은 별개의 부동산으로서 저당권의 객체가 되고 등기 없는 수목이나 미분리 과실도 명인방법을 갖추면 독립한 거래 객체가 된다 · 권한 없이 남의 토지에 경작한 농작물의 소유권은 판례상 경작자에게 있다"]]},{"t":"table","title":"종물","head":["주제","내용"],"rows":[["종물의 요건","종물은 주물의 상용에 이바지하도록 부속시킨 자기 소유의 다른 물건이어서 주물과 종물의 소유자가 같아야 하고(제100조 제1항) 독립한 물건이므로 부동산도 종물이 될 수 있다 · 주물 자체의 경제적 효용에 계속적으로 이바지해야 하므로 소유자의 상용에 제공될 뿐이거나 일시적으로 돕는 물건은 종물이 아니다 · 몽리농지의 양수장시설은 종물이지만 건물 안 정화조는 건물의 구성부분이다"],["종물은 주물의 처분에 따른다","처분에는 매매 같은 채권적 처분과 압류 같은 공법상 처분도 포함되고 저당권의 효력도 종물에 미친다(제358조) · 이 규정은 임의규정이어서 종물만 따로 처분하거나 주물 처분에서 종물을 빼는 특약이 유효하다 · 주물을 점유로 시효취득해도 점유하지 않은 종물에는 효력이 미치지 않는다"],["종된 권리","주물·종물 법리는 권리 상호간에도 유추되고 종된 권리가 되려면 다른 권리의 경제적 효용에 이바지하는 관계여야 한다 · 이미 변제기에 도달한 이자채권은 원본채권과 독립한 채권이어서 원본채권을 양도해도 별도 의사표시가 없으면 함께 넘어가지 않는다"]]},{"t":"vs","title":"천연과실과 법정과실","cols":[{"name":"천연과실","items":["물건의 용법에 따라 수취하는 산출물이고 유기물에 한하지 않는다(제101조)","원물에서 분리하는 때 수취할 권리자에게 속한다(제102조)"]},{"name":"법정과실","items":["물건의 사용대가로 받는 금전 기타 물건이다(제101조)","수취할 권리의 존속기간일수의 비율로 취득한다(제102조)","토지·건물의 차임은 법정과실이고 건물 사용이익도 과실에 준하지만 주식배당금이나 국립공원 입장료는 민법상 과실이 아니다"]}]},{"t":"def","term":"과실 귀속 규정","text":"특약으로 달리 정할 수 있는 임의규정이고 전세권자처럼 사용·수익권이 있는 자도 수취권자가 된다"}],"6":[{"t":"table","title":"법률행위 일반","head":["주제","내용"],"rows":[["종류와 요건","유언·유증·소유권 포기는 상대방 없는 단독행위, 채무면제·채권양도는 이행의 문제를 남기지 않는 준물권행위, 대리권 수여는 비출연행위, 사용대차는 무상행위, 근보증계약은 요식행위, 어음행위는 무인행위다 · 의사표시의 존재 같은 성립요건은 효과를 주장하는 자가, 효력요건의 흠결은 효과를 다투는 자가 증명한다 · 의사능력은 일반 효력요건이고 법정대리인 동의, 대리권, 기한 도래, 기본재산 처분 허가는 특별효력요건이며 농지취득자격증명은 원인 계약의 효력발생요건이 아니다"],["목적의 확정과 가능","목적은 성립 당시 확정되어 있거나 장차 확정할 수 있으면 되고 확정할 수 없으면 무효다 · 불능은 사회통념으로 판단해 물리적으로 가능해도 사회통념상 불가능하면 불능이다 · 계약 전에 건물이 불타 없어졌으면 원시적 불능으로 무효지만 계약 후 소실은 후발적 불능이어서 계약은 유효하고 남의 물건 매매도 원칙적으로 유효하다"],["강행규정과 단속규정","선량한 풍속 기타 사회질서와 관계없는 규정(임의규정)과 다른 합의는 효력이 있다(제105조) · 효력규정 위반은 무효이고 추인해도 유효가 되지 않으며 상대방이 선의·무과실이어도 표현대리나 비진의표시 법리로 구제되지 않는다 · 단속규정 위반은 원칙적으로 사법상 유효해 개업공인중개사의 직접거래가 그 예이고 중개수수료 한도 초과분, 비의료인과의 병원 동업, 토지거래허가 잠탈, 면허대여의 방편인 양도계약은 무효다"],["법률행위의 해석","표시된 내용의 확정은 사실인정이고 그 의미를 밝히는 해석은 법률적 판단이다 · 쌍방이 같은 물건을 의도했다면 계약서에 다른 물건을 잘못 적어도 의도한 물건에 계약이 성립하고(자연적 해석) 유언도 자연적 해석이 우선하며 규범적 해석은 상대방 입장의 합리적 사람이 이해하는 객관적 의미를 따른다 · 모순된 계약서가 여럿이면 마지막 문서가 우선하고 임의규정과 다른 사실인 관습은 의사가 불명확할 때 따르며 한쪽 해석에 따르기로 한 약정은 법원을 구속하지 못한다"]]},{"t":"table","title":"반사회질서 법률행위","head":["주제","내용"],"rows":[["판단","사회질서에 반하는 법률행위는 개별 강행법규 위반이 없어도 무효이며(제103조) 법률행위 당시를 기준으로 판단한다 · 내용 자체가 아니어도 반사회적 조건이 붙거나 표시되거나 상대방에게 알려진 동기가 반사회적이면 무효이고 부첩관계 종료를 해제조건으로 한 증여는 계약 전체가 무효다 · 보험금을 노린 보험계약은 상대방이 몰랐어도 무효이고 이 무효는 선의의 제3자에게도 대항하며 추인할 수 없다"]]},{"t":"vs","title":"반사회질서의 예","cols":[{"name":"반사회질서에 해당하는 예","items":["형사사건의 성공보수약정, 어떤 경우에도 이혼하지 않겠다는 약정","수사기관 허위진술의 대가 약정, 변호사 아닌 자의 승소 대가 약정","지방자치단체가 사업승인과 관련해 받기로 한 기부금 증여, 이중매매에 적극 가담한 매수는 무효다","대리인이 매도인의 배임에 적극 가담했으면 본인이 몰랐어도 무효이고 과도하게 무거운 위약벌도 무효가 될 수 있다"]},{"name":"반사회질서가 아닌 예","items":["민사사건 성공보수약정, 부첩관계를 끝내며 위로금을 주기로 한 약정","비자금을 소극적으로 숨기려는 임치, 강제집행을 면하려는 허위 근저당권설정(허위표시로 무효일 뿐), 양도소득세 회피 목적의 명의신탁","해외파견 근로자의 의무근무 약정, 불가항력 손해를 한쪽이 지기로 한 특약은 제103조 위반이 아니다","성립과정에 강박을 썼다는 사정만으로도 반사회질서가 되지 않고 제110조로 취소할 문제다","도박채무 변제를 위해 대리권을 준 행위도 무효가 아니어서 그 대리행위로 산 선의의 제3자는 보호된다"]}]},{"t":"table","title":"불공정한 법률행위","head":["주제","내용"],"rows":[["요건","급부와 반대급부 사이에 거래상 객관적 가치로 따진 현저한 불균형이 있고 피해자의 궁박, 경솔 또는 무경험 중 하나가 있으며 폭리자가 이를 알고 이용하려는 의사가 있어야 한다(제104조) · 현저한 불균형만으로 궁박 등이 추정되지 않고 요건은 무효를 주장하는 자가 증명하며 법률행위 당시를 기준으로 판단한다 · 궁박에는 정신적·심리적 궁박과 스스로 초래한 궁박도 포함되고 무경험은 거래 일반의 경험부족이며 대리행위에서 경솔·무경험은 대리인을, 궁박은 본인을 기준으로 한다"],["효과와 범위","불공정한 법률행위는 절대적 무효여서 추인해도 유효가 되지 않고 선의의 제3자에게도 무효이며 그 불공정성을 다투지 않기로 한 부제소합의도 무효다 · 무효행위 전환 규정은 적용될 수 있고 피해자는 이행한 것의 반환을 청구할 수 있으며 아직 이행하지 않은 채무는 이행할 필요가 없다 · 대가 관계가 없는 부담 없는 증여와 경매에는 제104조가 적용되지 않는다"]]}],"7":[{"t":"table","title":"비진의표시","head":["주제","내용"],"rows":[["진의 아닌 의사표시","표시에 상응하는 내심의 효과의사가 없음을 표의자가 알면서 한 의사표시로서 표의자가 몰랐다면 착오다 · 표시된 대로 효력이 있는 것이 원칙이고 상대방이 진의 아님을 알았거나 과실로 몰랐을 때 무효이며 무효는 선의의 제3자에게 대항하지 못한다(제107조) · 무효를 주장하는 자가 증명하고 계약뿐 아니라 상대방 있는 단독행위에도 적용되며 대리행위에서는 대리인을 표준으로 판단한다"],["비진의표시가 아닌 경우","진의는 특정한 내용의 의사표시를 하려는 표의자의 생각이어서 강박에 못 이겨서라도 증여 의사를 표시했거나 대출 명의를 빌려주며 채무부담을 표시했다면 비진의표시가 아니다"],["적용 제외","혼인·입양에는 제107조가 적용되지 않아 혼인할 의사가 없으면 상대방이 믿었어도 무효이고 공무원 사직 같은 사인의 공법행위에도 적용되지 않아 강요로 낸 사직서도 표시대로 효력이 생긴다 · 대리권 남용에는 제107조 제1항 단서와 함께 제3자 보호에 관한 제2항도 유추된다"]]},{"t":"table","title":"통정허위표시","head":["주제","내용"],"rows":[["요건과 당사자 사이 효과","진의와 다른 표시를 상대방과 통정하면 성립하고 다른 행위를 은닉할 목적은 필요 없다 · 당사자 사이에서는 무효여서 권리의무가 생기지 않고 누구든지 무효를 주장할 수 있으며 이미 지급한 대금은 반환을 청구할 수 있다(제108조 제1항) · 허위표시도 채권자취소권의 대상이 되고 추심을 위한 채권양도는 허위표시가 아니다"],["제108조 제2항의 제3자","허위표시의 외형을 토대로 새로운 법률상 이해관계를 맺은 자로서 가장채권의 양수인·가압류권자, 허위 전세권에 저당권을 설정받은 자와 그 채권을 압류한 자, 가장채무의 보증인, 파산관재인(파산채권자 일부만 선의여도)이 해당하고 가장 채권양도의 채무자는 해당하지 않는다"],["보호 범위","선의이면 과실이 있어도 보호되고 선의는 추정되어 악의는 무효를 주장하는 자가 증명한다 · 선의의 제3자에게는 누구도 무효로 대항하지 못하고 그 권리는 확정적이어서 그로부터 산 악의의 전득자도 보호되며 악의의 제3자에게서 산 선의의 전득자 역시 보호된다"]]},{"t":"table","title":"착오","head":["주제","내용"],"rows":[["착오 취소의 요건","법률행위 내용의 중요부분에 착오가 있어야 하고 착오가 없었으면 그 의사표시를 하지 않았을 것이며 표의자가 경제적 불이익을 입어야 하고 이는 취소하는 자가 증명한다(제109조) · 중대한 과실이 있으면 취소하지 못하나 그 증명책임은 상대방에게 있고 상대방이 착오를 알고 이용했다면 중과실이 있어도 취소할 수 있다 · 취소권 배제 합의는 유효하고 착오 취소는 선의의 제3자에게 대항하지 못하며 취소했다고 상대방에게 손해배상책임을 지지 않는다"],["동기의 착오","동기가 표시되어 법률행위의 내용이 되었을 때(그렇게 하자는 합의까지 있을 필요는 없다) 또는 상대방이 유발했을 때 취소할 수 있고 시가에 관한 착오나 막연한 장래 기대의 어긋남은 취소 사유가 아니다"],["착오 사례","양도소득세액 착오는 장래 사실이어도 착오가 될 수 있고 신원보증서류인 줄 알고 연대보증서에 서명한 것은 표시상의 착오, 근저당권 설정계약의 채무자 동일성 착오는 중요부분의 착오다 · 착오 취소는 하자담보책임과 별개로 가능하고 매도인이 해제한 뒤에도 할 수 있으며 소취하 같은 소송행위에는 적용되지 않지만 소취하합의는 사법상 계약이어서 취소할 수 있다"]]},{"t":"table","title":"사기·강박과 도달","head":["주제","내용"],"rows":[["사기·강박","신의칙상 고지의무를 어기면 부작위에 의한 기망이 되지만 상거래 관행상 허용되는 과장 광고는 기망이 아니고 부정한 이익을 노린 고소는 위법한 강박이나 정당한 손해배상을 얻으려는 고소는 그렇지 않다 · 의사결정의 자유를 완전히 빼앗는 강박에 의한 의사표시는 무효이지만 무효 주장 속에 취소 주장이 포함되지는 않는다 · 사기 취소는 하자담보책임과 경합하고 취소에 따른 부당이득반환청구권과 불법행위 손해배상청구권은 선택적으로 행사할 수 있으며 취소 후 이해관계를 맺은 선의의 제3자에게도 대항하지 못한다"],["제3자의 사기·강박","상대방 있는 의사표시에서 제3자가 사기·강박을 했으면 상대방이 알았거나 알 수 있었을 때만 취소할 수 있고(제110조 제2항) 상대방 없는 의사표시라면 언제든 취소할 수 있다 · 상대방의 대리인이 한 기망은 제3자의 사기가 아니어서 상대방(본인)이 몰랐어도 취소할 수 있지만 대리권 없는 피용자의 기망은 제3자의 사기다"],["도달주의","상대방 있는 의사표시는 도달한 때, 상대방 없는 의사표시는 표시행위가 끝난 때 효력이 생기고 도달주의는 채권양도 통지와 무권대리 추인 최고에도 적용되며 발신 후 표의자가 사망하거나 성년후견이 개시돼도 효력에 영향이 없다(제111조) · 도달은 상대방이 내용을 알 수 있는 객관적 상태에 놓이면 충분해 현실 수령이나 정당한 이유 없는 수령 거절과 무관하고 등기우편은 그 무렵 도달이 인정되나 보통우편은 추정되지 않으며 도달은 효력을 주장하는 자가 증명한다 · 제한능력자에게는 도달을 들어 대항하지 못하지만 법정대리인이 도달을 안 후에는 대항할 수 있고(제112조) 표의자가 과실 없이 상대방이나 그 소재를 모르면 공시송달로 송달할 수 있다(제113조)"]]}],"8":[{"t":"table","title":"대리의 범위와 수권행위","head":["주제","내용"],"rows":[["대리가 허용되는 범위","대리는 의사표시와 그에 준하는 행위에 인정되므로 채권양도 통지 같은 관념의 통지는 대리할 수 있지만 사실행위와 불법행위는 대리의 대상이 아니다 · 혼인처럼 본인의 의사결정이 절대적으로 필요한 신분행위는 대리할 수 없고 효과가 본인에게 귀속하려면 본인에게 권리능력이 있어야 한다 · 대리인에게 위임했어도 본인은 그 행위를 직접 할 수 있다"],["수권행위","임의대리권은 본인이 대리인에게 하는 상대방 있는 단독행위인 수권행위로 생기고 수권행위는 불요식이어서 묵시적으로도 할 수 있으며 대리인처럼 행동하는 것을 이의 없이 방임한 데서 추단될 수도 있다 · 수권행위는 위임 같은 내부 법률관계와 구별되므로 미성년 대리인은 대리행위를 취소할 수 없어도 본인과의 위임계약은 제한능력을 이유로 취소할 수 있다 · 대리인은 행위능력자일 필요가 없고(제117조) 본인도 대리인이 미성년자임을 이유로 대리행위를 취소하지 못한다"],["대리권의 범위","임의대리권의 범위는 수권행위로, 법정대리권의 범위는 법률로 정하고 권한을 정하지 않은 대리인은 보존행위와 객체의 성질을 바꾸지 않는 이용·개량행위만 할 수 있어(제118조) 예금을 주식으로 바꾸거나 처분하지 못한다 · 매매계약 체결의 대리권에는 중도금·잔금 수령권이 포함되고 체결·이행의 포괄적 대리권이면 대금지급기일도 연기할 수 있다 · 계약 체결 대리인에게는 해제권이나 해제의 의사표시 수령권, 합의해제권, 취소권이 없고 예금계약 체결권에 예금 처분권이, 영수권한에 채무 면제권이, 입찰 대리권에 경매신청 취하 동의권이 포함되지 않는다"]]},{"t":"table","title":"대리인의 제한","head":["주제","내용"],"rows":[["자기계약·쌍방대리","대리인은 본인의 허락이 없으면 자기계약이나 쌍방대리를 하지 못하지만 채무의 이행은 할 수 있고(제124조) 이 규정은 법정대리에도 적용된다 · 허락 없이 한 자기계약은 확정적 무효가 아니라 무권대리여서 본인이 추인하면 유효하고 본인에게 이익만 주는 채무 면제나 친권자가 자녀에게 하는 단순 증여는 금지 대상이 아니다 · 법무사의 등기신청 쌍방대리는 허용되지만 이해관계가 다른 여러 입찰자를 한 사람이 대리한 입찰은 무효다"],["각자대리·대리권 소멸","대리인이 여럿이면 법률이나 수권행위에 다른 정함이 없는 한 각자 본인을 대리한다(제119조) · 대리권은 본인의 사망, 대리인의 사망·성년후견 개시·파산으로 소멸하고 대리인의 한정후견 개시는 소멸사유가 아니다(제127조) · 임의대리권은 원인된 법률관계의 종료로 소멸하며 그 종료 전이라도 본인이 수권행위를 철회하면 소멸한다(제128조)"],["대리권 남용","대리인이 자기나 제3자의 이익을 꾀해 권한 내 행위를 한 경우 판례는 제107조 제1항 단서를 유추해 상대방이 그 배임 의도를 알았거나 알 수 있었으면 본인에게 효력이 없다고 본다 · 이렇게 무효가 되어도 이를 기초로 새로운 이해관계를 맺은 선의의 제3자는 제107조 제2항 유추로 보호된다"]]},{"t":"table","title":"현명·하자·복대리","head":["주제","내용"],"rows":[["현명","대리인이 본인을 위한 것임을 표시해야 본인에게 효력이 생기고 현명은 묵시적으로도 할 수 있다 · 표시하지 않으면 대리인 자신을 위한 것으로 보지만(추정이 아닌 간주) 상대방이 대리인으로서 한 것임을 알았거나 알 수 있었으면 본인에게 효력이 있다(제115조) · 위임장을 제시하고 계약서에 자기 이름만 적었어도 대리행위이고 수동대리에서는 상대방이 본인에 대한 의사표시임을 표시해야 하며 권한 위임이 없으면 양수인의 양도통지는 효력이 없다"],["대리행위의 하자와 증명책임","의사의 흠결, 사기·강박, 어떤 사정의 지·부지는 대리인을 표준으로 정하지만(제116조 제1항) 불공정 법률행위의 궁박은 본인을 기준으로 한다 · 특정한 법률행위를 위임받은 대리인이 본인의 지시에 따랐으면 본인은 자기가 안 사정이나 과실로 모른 사정에 관해 대리인의 부지를 주장하지 못한다(제116조 제2항) · 대리인의 사기·강박은 제3자의 것이 아니어서 상대방은 본인이 몰랐어도 취소할 수 있고 대리권의 존재는 대리행위의 효과를 주장하는 상대방이 증명한다"],["복대리","복대리인은 대리인이 자기 이름으로 선임한 본인의 대리인으로서 임의대리인이며 행위능력이 필요 없고 본인이나 제3자에 대해 대리인과 같은 권리의무가 있다(제123조) · 임의대리인은 본인의 승낙이나 부득이한 사유가 있어야 선임할 수 있고(성질상 대리인이 직접 처리할 필요가 없으면 묵시적 승낙이 인정되나 아파트 분양업무처럼 능력이 중요하면 명시적 승낙이 필요하다) 선임감독 책임을 지며 본인이 지명한 경우는 부적임을 알고도 통지·해임을 게을리한 때만 책임진다 · 법정대리인은 언제든 선임할 수 있지만 전적인 책임을 지고 부득이한 사유면 선임감독 책임만 지며 복대리권은 대리인의 대리권 범위를 넘지 못하고 그 대리권이 소멸하면 함께 소멸하지만 복대리인을 선임해도 대리인의 대리권은 남는다"]]}],"9":[{"t":"table","title":"표현대리","head":["주제","내용"],"rows":[["표현대리의 성질","권리외관이론에 기초해 본인에게 책임을 지우는 제도이고 성립해도 무권대리가 유권대리로 바뀌지 않는다 · 유권대리와 요건·효과가 다르므로 유권대리 주장 속에 표현대리 주장이 포함되지 않아 법원이 따로 판단할 의무가 없다 · 성립하면 본인은 계약상 책임을 지고 상대방에게 과실이 있어도 과실상계로 책임을 줄일 수 없으며 강행법규 위반으로 무효인 행위에는 표현대리가 성립하지 않는다"],["대리권 수여 표시(제125조)","제3자에게 타인에게 대리권을 주었다고 표시한 자는 그 범위에서 타인이 한 법률행위에 책임을 지지만 제3자가 대리권 없음을 알았거나 알 수 있었으면 책임이 없다 · 대리권을 추단할 수 있는 직함의 사용을 승낙한 것도 수여 표시가 되며 본인과 행위자 사이 법률관계의 성질·효력은 묻지 않는다 · 납세번호증 사용을 허락하거나 보증 설 의사를 채권자에게 밝힌 것만으로는 수여 표시가 아니다"],["권한을 넘은 표현대리(제126조)","대리인이 권한 외의 행위를 하고 상대방이 권한이 있다고 믿을 정당한 이유가 있으면 본인이 책임진다 · 기본대리권은 월권행위와 같은 종류일 필요가 없고 법정대리권, 사실혼 부부의 일상가사대리권, 등기신청 같은 공법상 행위의 대리권, 복임권 없이 선임된 복대리인의 권한도 기본대리권이 된다 · 대리인이 본인 행세를 하며 본인 명의로 직접 법률행위를 한 경우는 대리행위가 아니어서 원칙적으로 제126조가 적용되지 않는다"],["정당한 이유","대리행위 당시의 사정으로 판단하며 변론종결 시가 기준이 아니고 대리행위의 유효를 주장하는 상대방이 증명한다 · 상대방의 과실 판단에 표현대리인의 주관적 사정은 고려하지 않으며 제126조로 보호받는 상대방은 대리인과 직접 법률행위를 한 자에 한정된다"],["대리권 소멸 후(제129조)","대리권의 소멸은 선의의 제3자에게 대항하지 못하지만 제3자가 과실로 소멸을 몰랐다면 그렇지 않다 · 대리권 소멸 후 복대리인을 선임해 대리행위를 하게 한 경우에도 성립하고 제129조로 인정되는 범위를 넘는 행위를 하면 제126조의 표현대리가 겹쳐 성립할 수 있다"]]},{"t":"table","title":"무권대리의 추인과 최고·철회","head":["주제","내용"],"rows":[["추인","무권대리인이 한 계약은 본인이 추인하지 않으면 본인에게 효력이 없고(제130조) 추인은 상대방 있는 단독행위로서 묵시적으로도 할 수 있어 본인이 매매대금을 받으면 추인으로 볼 수 있지만 상속인이 인감증명서를 건넨 것만으로는 추인이 아니다 · 추인은 다른 의사표시가 없으면 계약 시로 소급하되 제3자의 권리를 해하지 못하고(제133조) 일부 추인은 상대방 동의가 없으면 무효다 · 추인은 무권대리인이나 전득자 같은 승계인에게도 할 수 있지만 상대방에게 하지 않으면 상대방이 그 사실을 알 때까지 대항하지 못하고(제132조) 추인을 거절한 뒤나 상대방이 철회한 뒤에는 추인할 수 없다"],["상대방의 최고권","상대방은 상당한 기간을 정해 본인에게 추인 여부의 확답을 최고할 수 있고 대리권 없음을 알았어도 최고할 수 있으며 본인이 기간 내에 확답을 발하지 않으면 추인을 거절한 것으로 본다(제131조)"],["상대방의 철회권","철회는 계약 당시 대리권 없음을 몰랐던 상대방만 본인의 추인이 있을 때까지 본인이나 무권대리인에게 할 수 있고(제134조) 상대방의 악의는 철회의 효과를 다투는 본인이 증명한다 · 유효한 철회가 있으면 계약은 확정적으로 무효가 된다"]]},{"t":"table","title":"무권대리인의 책임","head":["주제","내용"],"rows":[["책임","대리권을 증명하지 못하고 본인의 추인도 받지 못한 무권대리인은 상대방의 선택에 따라 계약을 이행하거나 손해를 배상할 책임을 진다(제135조 제1항) · 이 책임은 무과실책임이어서 제3자의 위법행위로 무권대리가 생겼어도 면책되지 않고 계약의 위약금 약정도 적용된다"],["책임이 없는 경우","상대방이 대리권 없음을 알았거나 알 수 있었을 때 또는 무권대리인이 제한능력자일 때는 이 책임이 없다(제135조 제2항)"],["본인 상속","무권대리인이 본인을 단독상속한 뒤 본인 지위에서 추인을 거절하거나 무권대리를 이유로 계약의 무효를 주장하는 것은 신의칙에 반해 허용되지 않는다"],["단독행위의 무권대리","상대방이 행위 당시 동의했거나 대리권을 다투지 않은 때에만 무권대리 규정이 준용된다(제136조)"]]}],"10":[{"t":"table","title":"무효","head":["주제","내용"],"rows":[["무효의 성질","무효인 법률행위는 성립한 때부터 당연히 효력이 없고 취소 원인이 있으면 무효인 행위도 취소할 수 있다(이중효) · 강행규정 위반, 반사회질서, 불공정 법률행위, 원시적 전부불능의 무효는 선의의 제3자에게도 대항하지만 비진의표시·허위표시의 무효는 선의의 제3자에게 대항하지 못한다 · 허위표시가 무효라고 그 속의 은닉행위까지 당연히 무효가 되지는 않는다"],["일부무효","법률행위의 일부가 무효이면 전부를 무효로 하지만 그 부분이 없더라도 법률행위를 했으리라고 인정되면 나머지는 유효하다(제137조) · 이 조문은 임의규정이고 일체성이 있는 여러 법률행위에도 적용되며 효력규정 위반으로 적용될 때는 가정적 의사를 찾으면서 그 규정의 입법취지를 함께 고려한다"],["무효행위의 전환과 추인","무효인 행위가 다른 법률행위의 요건을 갖추고 당사자가 무효를 알았다면 그것을 의욕했으리라 인정되면 다른 법률행위로서 효력이 있고(제138조) 불공정 법률행위로 무효인 매매에도 적용된다 · 무효인 행위는 추인해도 효력이 생기지 않지만 당사자가 무효임을 알고 무효 원인이 소멸한 뒤 추인하면 새로운 법률행위로 보며 소급효는 없다(제139조) · 취소된 행위도 이 요건을 갖추면 추인할 수 있고 무효 등기를 유용하기로 한 약정도 약정한 때부터 효력이 생긴다"],["소급효가 있는 추인","무권대리행위에 대한 본인의 추인은 계약 시로, 무권리자의 처분행위에 대한 권리자의 추인은 처분 시로 소급해 유효가 된다 · 무효행위의 추인이나 무효 등기의 유용에는 소급효가 없다"]]},{"t":"table","title":"유동적 무효(토지거래허가)","head":["주제","내용"],"rows":[["유동적 무효","허가를 받을 것을 전제로 한 허가구역 내 토지 매매는 허가 전까지 채권적 효력도 없는 유동적 무효이고 허가를 받거나 허가구역 지정이 해제되면 계약 시로 소급해 확정적으로 유효가 되어 다시 계약할 필요가 없다 · 처음부터 허가를 배제·잠탈하는 계약은 확정적 무효여서 뒤에 지정이 해제돼도 유효가 되지 않고 쌍방이 협력의무 이행 거절을 명백히 하거나 정지조건 불성취가 확정되면 확정적 무효가 되며 이때는 귀책사유 있는 자도 무효를 주장할 수 있다"],["허가 전 당사자의 권리","허가 전에는 매수인이 허가조건부 이전등기를 청구하거나 계약금을 부당이득으로 반환청구할 수 없고 대금 미지급이나 협력의무 위반을 이유로 계약을 해제할 수도 없다 · 다만 협력의무 이행은 소로 구할 수 있고 협력의무 불이행에 대한 손해배상액 약정은 유효하며 협력의무와 대금지급의무는 동시이행관계가 아니다 · 허가신청이 접수된 뒤라도 매도인은 계약금 배액을 상환하고 해제할 수 있다"]]},{"t":"table","title":"취소","head":["주제","내용"],"rows":[["취소권자와 효과","취소는 제한능력자, 착오·사기·강박으로 의사표시를 한 자, 그 대리인 또는 승계인만 할 수 있고(제140조) 제한능력자는 단독으로 취소할 수 있으며 그 취소를 다시 취소할 수는 없다 · 취소된 행위는 처음부터 무효로 보고 제한능력자는 받은 이익이 현존하는 한도에서 상환한다(제141조) · 가분적이거나 일부가 특정되면 일부취소도 할 수 있고 계속된 근로계약이나 혼인·입양의 취소는 장래에 향해서만 효력이 있지만 사기로 인한 협의이혼의 취소에는 소급효가 있다"],["추인","취소의 원인이 소멸한 뒤 취소할 수 있는 행위임을 알고 상대방에 대한 의사표시로 해야 하고 묵시적으로도 할 수 있으며 추인하면 다시 취소하지 못한다(제143조, 제144조) · 법정대리인이나 후견인의 추인은 취소 원인이 소멸하기 전에도 할 수 있으므로 미성년자 본인은 성년이 되기 전에 단독으로 추인할 수 없다"],["법정추인","추인할 수 있는 후에 취소권자가 이의를 보류하지 않고 전부나 일부의 이행, 이행의 청구, 경개, 담보의 제공, 취득한 권리의 양도, 강제집행을 하면 추인한 것으로 보고(제145조) 취소권이 있음을 알았는지는 묻지 않는다 · 이행거절이나 상대방이 한 양도는 법정추인 사유가 아니다"],["취소권 행사기간","취소권은 추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년 내에 행사해야 하고(제146조) 이 기간은 제척기간이다"]]}],"11":[{"t":"table","title":"조건과 기한","head":["주제","내용"],"rows":[["조건과 기한의 구별","조건은 효력의 발생·소멸을 장래의 불확실한 사실에, 기한은 장래 반드시 오는 사실에 의존시키는 부관이어서 시기가 확정되지 않아도 반드시 오는 사실이면 기한이다 · 특정한 제3자가 사망하면 증여하겠다는 계약은 불확정기한부이고 사실이 발생하지 않는 것으로 확정된 때에도 이행해야 한다고 보는 것이 합리적이면 그 사실은 조건이 아니라 불확정기한이다 · 유언이 사망으로 효력이 생기는 것은 법이 정한 효력발생 시기일 뿐 정지조건이 아니다"],["조건의 성립과 증명","조건이 되려면 조건의사가 외부에 표시되어야 하고 정지조건부 법률행위는 이미 성립해 있으며 조건이 성취된 때 효력이 생긴다 · 법률행위에 정지조건이 붙었다는 사실은 효과 발생을 다투는 자가, 조건이 성취되었다는 사실은 효력 발생을 주장하는 자가 증명한다 · 약혼예물의 수수는 혼인 불성립을 해제조건으로 하는 증여와 비슷하다"],["조건에 친하지 않은 행위","혼인·입양·상속의 승인 같은 신분행위, 상계 같은 소급효 있는 단독행위, 어음·수표행위에는 조건을 붙일 수 없고 상계에는 기한도 붙이지 못한다 · 이런 행위에 조건을 붙이면 조건만이 아니라 법률행위 전체가 무효이며 물권행위에는 조건을 붙일 수 있다"]]},{"t":"table","title":"조건의 효과","head":["주제","내용"],"rows":[["조건 성취의 효과","정지조건은 성취한 때부터 효력이 생기고 해제조건은 성취한 때부터 효력을 잃으며 당사자가 소급 의사를 표시한 경우에만 소급한다(제147조) · 조건 성취로 불이익을 받을 자가 신의성실에 반해 성취를 방해하면 상대방은 성취를 주장할 수 있고 방해는 과실이어도 되며 성취 시점은 방해가 없었다면 성취되었으리라 추산되는 때다(제150조) · 이익을 받을 자가 신의성실에 반해 성취시킨 경우에는 상대방이 불성취를 주장할 수 있다"],["불법조건·기성조건·불능조건","조건이 선량한 풍속 기타 사회질서에 위반하면 조건만이 아니라 그 법률행위가 무효다(제151조 제1항) · 법률행위 당시 이미 성취한 조건은 정지조건이면 조건 없는 법률행위, 해제조건이면 무효가 된다 · 이미 성취할 수 없는 불능조건은 해제조건이면 조건 없는 법률행위, 정지조건이면 무효가 된다"],["조건부·기한부 권리","조건의 성취가 미정인 권리의무도 일반규정에 따라 처분, 상속, 보존, 담보로 할 수 있고(제149조) 기한부 권리도 담보로 할 수 있다 · 조건부·기한부 법률행위의 당사자는 조건 성취나 기한 도래로 생길 상대방의 이익을 해하지 못한다"]]},{"t":"table","title":"기한","head":["주제","내용"],"rows":[["기한의 효력과 불확정기한","시기 있는 법률행위는 기한이 도래한 때부터 효력이 생기고 종기 있는 법률행위는 기한이 도래한 때부터 효력을 잃으며(제152조) 기한에는 소급효가 없다 · 불확정한 사실이 발생한 때를 이행기로 정했으면 그 사실이 발생한 때는 물론 발생이 불가능하게 된 때에도 기한이 도래한다"],["기한의 이익","기한은 채무자의 이익을 위한 것으로 추정하므로 채권자에게 이익이 있다는 것은 채권자가 증명한다(제153조 제1항) · 무이자 소비대차에서는 채무자만, 이자부 소비대차에서는 채권자도 기한의 이익을 가진다 · 기한의 이익은 포기할 수 있지만 상대방의 이익을 해하지 못해 이자부 소비대차의 채무자는 상대방의 손해를 배상하고 기한 전에 변제할 수 있다"],["기한이익 상실 특약","정지조건부임이 명백한 특별한 사정이 없으면 형성권적 특약으로 추정된다 · 형성권적 특약은 상실사유가 생겨도 채권자가 기한이익을 상실시키는 의사표시를 해야 이행기가 도래하므로 할부채무 전액의 소멸시효도 그 의사표시를 한 때부터 진행한다 · 정지조건부 특약이면 사유 발생과 동시에 당연히 이행기가 도래한다"]]}],"12":[{"t":"table","title":"기간 계산의 기본","head":["주제","내용"],"rows":[["적용 범위","기간의 계산은 법령, 재판상의 처분 또는 법률행위에 다른 정함이 없으면 민법 규정에 따르므로(제155조) 당사자가 합의로 달리 정할 수 있다 · 초일 불산입을 정한 제157조도 임의규정이어서 초일을 산입하기로 약정할 수 있다"],["시·분·초 단위","기간을 시, 분, 초로 정한 때에는 즉시로부터 기산한다(제156조) · 오후 3시부터 5시간이라고 했다면 그 시각부터 바로 계산한다"],["일·주·월·연 단위의 기산점","기간을 일, 주, 월 또는 연으로 정하면 초일을 산입하지 않지만 그 기간이 오전 0시부터 시작하면 초일을 산입한다(제157조) · 그래서 4월 17일 10시 30분에 지금부터 1개월이라고 하면 4월 18일 0시가 기산점이고 다가오는 2월 16일부터 5일간이라고 하면 2월 16일이 기산점이다 · 기산점이 되는 날이 공휴일이어도 기산점은 그날 그대로다"]]},{"t":"table","title":"만료점","head":["주제","내용"],"rows":[["역에 의한 계산과 만료점","주, 월, 연으로 정한 기간은 일로 환산하지 않고 역에 따라 계산하며 기간말일의 종료로 만료한다(제159조, 제160조 제1항) · 주, 월, 연의 처음부터 기산하지 않으면 최후의 주, 월, 연에서 기산일에 해당한 날의 전일로 만료하므로 4월 18일 기산 1개월은 5월 17일 24시에 끝난다 · 초일을 산입하기로 약정한 4월 23일 15시의 6개월 차용이면 10월 22일 24시까지 갚아야 한다"],["해당일이 없는 경우","월 또는 연으로 정한 기간에서 최종의 월에 해당일이 없으면 그 월의 말일로 만료한다(제160조 제3항) · 1월 29일 정오와 1월 31일 정오에 각각 오늘부터 1개월이라고 하면 둘 다 2월 말일에 만료한다"],["말일이 토요일·공휴일인 경우","기간의 말일이 토요일 또는 공휴일이면 기간은 그 익일로 만료한다(제161조) · 이 조문은 2007년 개정으로 토요일을 넣었으므로 말일이 토요일이면 일요일도 공휴일이어서 그다음 월요일에 만료한다 · 이 규정은 기간의 만료점에만 적용되고 기산점에는 적용되지 않는다"]]},{"t":"table","title":"나이와 역산","head":["주제","내용"],"rows":[["나이 계산","나이는 출생일을 산입하여 만 나이로 계산하고 연수로 표시하되 1세에 이르지 않으면 월수로 표시할 수 있다(제158조) · 판례는 정년이 60세라는 것을 만 60세에 도달하는 날로 본다"],["역산하는 기간","어느 날부터 소급해 계산하는 기간에도 같은 원칙이 적용되어 기준일은 넣지 않고 그 전날부터 거꾸로 센다 · 선거일이 2026년 4월 24일일 때 선거일 전 3년간은 2023년 4월 24일 0시부터 2026년 4월 23일 24시까지다"]]}],"13":[{"t":"table","title":"소멸시효의 대상과 기간","head":["주제","내용"],"rows":[["소멸시효의 대상","소유권, 점유권, 인격권 같은 비재산권, 피담보채권이 남아 있는 담보물권과 유치권, 공유관계가 존속하는 동안의 공유물분할청구권, 소유권에 기한 물권적 청구권, 진정명의회복을 원인으로 한 등기청구권, 합의해제에 따른 매도인의 등기말소청구권은 소멸시효에 걸리지 않는다 · 부동산을 인도받아 점유하는 매수인의 등기청구권도 시효로 소멸하지 않고 그 부동산을 다시 팔아 넘겨준 경우도 같다 · 반면 소유권 침해로 인한 손해배상청구권, 취소에 따른 대금반환청구권, 근저당권설정등기청구권, 점유를 잃은 취득시효 완성자의 등기청구권(점유 상실 때부터 10년)은 시효에 걸리고 동시이행항변권이 붙은 채권도 마찬가지다"],["시효기간","채권은 10년, 채권과 소유권 이외의 재산권은 20년이고(제162조) 이자·사용료 등 1년 이내 기간으로 정한 금전 지급 채권, 도급받은 자의 공사 채권, 변호사·변리사·공증인·공인회계사·법무사의 직무 채권, 상인이 판매한 상품의 대가는 3년이다(제163조) · 숙박료·음식료, 동산 사용료, 연예인의 임금과 그에게 공급한 물건의 대금은 1년이고(제164조) 세무사의 직무 채권은 열거되지 않아 10년이며 지연손해금은 원본채권의 시효를 따른다 · 판결, 파산절차, 재판상 화해·조정으로 확정된 채권은 단기시효 대상이라도 10년이지만 확정 당시 변제기가 오지 않은 채권에는 적용되지 않고 주채무가 판결로 10년이 되어도 보증채무의 기간까지 늘지는 않는다(제165조)"],["기산점","시효는 권리를 행사할 수 있는 때부터 진행하므로(제166조) 정지조건부 권리는 조건 성취 때, 불확정기한은 기한이 객관적으로 도래한 때, 기한 없는 부당이득반환청구권은 권리가 발생한 때, 이행불능 손해배상청구권은 불능 때, 신축 건물의 이전등기청구권은 완공 때, 무권대리인에 대한 청구권은 선택권을 행사할 수 있는 때부터 진행한다 · 부작위채권은 위반행위를 한 때부터 진행하고 변제기 후 기한을 유예하면 유예한 변제기부터 다시 진행하며 임대차 종료 후 보증금을 받으려고 목적물을 점유하는 동안 보증금반환채권의 시효는 진행하지 않는다 · 기산일은 변론주의가 적용되어 법원은 당사자가 주장한 기산일을 기준으로 판단한다"]]},{"t":"table","title":"시효의 중단","head":["주제","내용"],"rows":[["재판상 청구와 최고","시효를 주장하는 채무자가 낸 소에 채권자가 응소해 권리를 주장하고 받아들여지면 중단되지만 물상보증인이 낸 채무부존재확인 소송에 응소한 것은 채무자에 대한 중단사유가 아니다 · 소가 각하·기각·취하되면 중단 효력이 없으나 6월 내에 재판상 청구 등을 하면 최초 청구 때 중단된 것으로 보고(제170조) 취하된 소는 최고의 효력이 있으며 최고는 6월 내에 재판상 청구 등을 해야 중단 효력이 있다(제174조) · 대항요건을 갖추지 못한 채권양수인의 청구, 형사소송의 배상명령 신청도 중단사유이고 재판상 청구로 중단된 시효는 재판이 확정된 때부터 새로 진행하며 이미 시효가 완성된 뒤에는 중단을 인정할 수 없다"],["압류·가압류와 승인","압류·가압류·가처분은 권리자의 청구나 법률 규정 위반으로 취소되면 중단 효력이 없고(제175조) 물상보증인 재산을 압류했으면 채무자에게 통지해야 채무자에 대해 중단되며(제176조) 가압류의 중단 효력은 집행보전 효력이 존속하는 동안 계속된다 · 승인은 권리의 존재를 안다는 뜻을 표시하는 관념의 통지로서 처분의 능력이나 권한이 필요 없고(제177조) 묵시적으로도 할 수 있으며 상대방에게 도달한 때 효력이 생기고 승인 사실은 채권자가 증명한다 · 시효 진행 전이나 아직 생기지 않은 장래 채권에 대한 승인은 중단사유가 아니고 시효 완성 전 일부 변제는 나머지 전부에 대한 승인이 된다"],["중단의 인적 범위","시효중단은 당사자와 그 승계인 사이에만 효력이 있고(제169조) 승계인은 중단 효과가 생긴 뒤 그 권리를 승계한 자를 말하며 조합의 손해배상청구권이 중단된 뒤 지분을 양수한 자에게도 미친다 · 주채무자에 대한 중단은 보증인에게 효력이 있지만 보증인에 대한 청구나 보증채무의 중단은 주채무를 중단시키지 않는다 · 연대채무자 1인에 대한 이행청구는 다른 연대채무자에게 미치고 채권자대위소송은 채무자의 제3채무자에 대한 채권을 중단시키며 요역지 공유자 1인의 지역권 시효중단은 다른 공유자에게도 미친다"]]},{"t":"table","title":"시효 완성과 제척기간","head":["주제","내용"],"rows":[["시효 완성의 효과와 원용권자","소멸시효는 기산일에 소급하여 효력이 생기고(제167조) 주된 권리가 시효로 소멸하면 이자 같은 종속된 권리도 소멸한다(제183조) · 시효를 원용할 수 있는 사람은 시효로 직접 이익을 받는 자로서 보증인, 물상보증인, 담보가등기나 유치권이 붙은 부동산의 매수인, 사해행위의 수익자가 해당하고 주채무가 시효로 소멸하면 보증채무도 당연히 소멸한다 · 후순위 저당권자는 선순위 피담보채권의 시효소멸로 간접적 이익만 얻으므로 원용할 수 없다"],["시효이익의 포기·정지","시효이익은 미리 포기하지 못하고 시효를 배제·연장·가중하는 약정은 무효지만 단축·경감하는 약정은 유효하다(제184조) · 완성 후 채무를 승인하거나 일부 변제하면 전체에 대한 포기로 추정되고(간주가 아님) 포기한 때부터 새로 시효가 진행하며 포기의 효력은 보증인이나 저당부동산의 제3취득자에게 미치지 않는다 · 기간만료 전 6개월 내에 제한능력자에게 법정대리인이 없으면 능력자가 되거나 법정대리인이 취임한 때부터 6개월, 부부 사이의 권리는 혼인관계 종료 후 6개월, 천재 기타 사변이면 그 사유가 끝난 때부터 1월 내에는 시효가 완성되지 않는다(제179조~제182조)"],["제척기간","권리가 발생한 때부터 기산하고 중단·정지가 없으며 기간이 지나면 원용 없이 당연히 소멸하므로 포기할 수 없고 법원이 직권으로 조사한다 · 형성권(취소권, 매매예약완결권)뿐 아니라 청구권도 제척기간에 걸릴 수 있고 출소기간이 아니면 재판 밖에서 행사해도 되지만 상속회복청구권과 점유물반환청구권의 기간은 소를 제기해야 지키는 출소기간이다 · 매매예약완결권은 약정이 없으면 예약 성립일부터 10년이고 당사자가 더 긴 기간을 정할 수 있으며 행사 시기를 따로 약정했어도 기간은 원칙적으로 완결권이 발생한 때부터 기산한다"]]}]};
